$html = @'
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff sign in</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#0f274d,#2563eb);font-family:Inter,system-ui;color:#10233f}.card{width:min(420px,calc(100% - 32px));background:#fff;border-radius:20px;padding:36px;box-shadow:0 25px 70px #071a3866}h1{margin:0 0 8px}p{color:#667085;margin-bottom:25px}label{display:block;font-weight:700;font-size:14px;margin:16px 0 7px}input{width:100%;box-sizing:border-box;padding:13px;border:1px solid #cfd8e5;border-radius:9px;font:inherit}button{width:100%;margin-top:22px;padding:13px;border:0;border-radius:9px;background:#2563eb;color:#fff;font-weight:800;cursor:pointer}.error{color:#b42318;margin-top:14px}.links{text-align:center;margin-top:20px;font-size:14px}.links a{color:#2563eb;font-weight:700;text-decoration:none}</style></head><body><section class="card"><h1>Welcome back</h1><p>Sign in to your IT support workspace.</p><form id="login"><label>Email or username</label><input id="loginId" required><label>Password</label><input id="pass" type="password" required><button>Sign in</button></form><div id="error" class="error"></div><div class="links"><a href="/signup">Create a user account</a> · <a href="/create-ticket">Public ticket form</a></div></section><script>login.addEventListener('submit',async e=>{e.preventDefault();const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login:loginId.value,password:pass.value})});const j=await r.json();if(!r.ok){error.textContent=j.message;return}sessionStorage.setItem('token',j.token);if(j.user.role==='user')location.href='/user/';else location.href='/dashboard/'})</script></body></html>
'@
Set-Content dashboard/login.html $html -NoNewline
